def countComponents(self, n: int, edges: list[list[int]]) -> int:
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    visited = [False] * n

    def dfs(node: int) -> None:
        visited[node] = True
        for nxt in adj[node]:
            if not visited[nxt]:
                dfs(nxt)

    count = 0
    for i in range(n):
        if not visited[i]:
            count += 1
            dfs(i)
    return count

